using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalUtilityBlend{
const string Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas";
static BindingFlags Flags=BindingFlags.Static|BindingFlags.NonPublic;static Type T=typeof(FinalAtlasGardens);
static object Call(string n,params object[] a)=>T.GetMethod(n,Flags).Invoke(null,a);
static V Field<V>(object o,string n)=>(V)o.GetType().GetField(n).GetValue(o);
static FinalUtilityBlend(){EditorApplication.update+=Poll;}
static void Poll(){if(!File.Exists("FinalUtilityBlend.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalUtilityBlend.request");Run();}
static bool At(object s,Vector3 p,out Vector2 uv){object[] a={s,p,0f,Vector2.zero,Vector4.zero,Vector4.zero};bool okay=(bool)Call("At",a);uv=(Vector2)a[3];return okay&&Mathf.Abs((float)a[2]-p.y)<.6f;}
static object Host(object[] all,Vector3 p){return all.Where(s=>{var b=Field<Bounds>(s,"b");return p.x>=b.min.x-.01f&&p.x<=b.max.x+.01f&&p.z>=b.min.z-.01f&&p.z<=b.max.z+.01f;}).FirstOrDefault(s=>At(s,p,out var u));}
static void Photo(Scene s,Vector3 p,Vector3 target,string n)=>typeof(FinalPNGCityDetails).GetMethod("Capture",Flags).Invoke(null,new object[]{s,p,target,n});
static void Run(){var log=new StringBuilder();try{
var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!scene.isLoaded)throw new Exception("Target scene not loaded");
var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var group=root.transform.Find("City Atlas Gardens and Utilities");
var chunks=group.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("UtilityCovers_")&&f.gameObject.activeInHierarchy&&f.GetComponent<MeshRenderer>().enabled).ToArray();
var surfaces=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.sharedMesh&&f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterial&&new[]{"City PNG Markings","Road Atlas"}.Contains(f.GetComponent<MeshRenderer>().sharedMaterial.name)).Select(f=>Call("Read",f)).Where(s=>new[]{0,2,3}.Contains(Field<int>(s,"layer"))).ToArray();
var walks=surfaces.Where(s=>Field<int>(s,"layer")==3&&Field<float>(s,"area")>20&&Mathf.Max(Field<Bounds>(s,"b").size.x,Field<Bounds>(s,"b").size.z)>=25&&Mathf.Min(Field<Bounds>(s,"b").size.x,Field<Bounds>(s,"b").size.z)>=1.5f).ToArray();
string backup="FinalEnvironmentRoadBackup/UtilityBlend-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);
var mat=AssetDatabase.LoadAssetAtPath<Material>(Out+"/City Garden Utility Atlas.mat");File.Copy(AssetDatabase.GetAssetPath(mat),backup+"/Before.mat");foreach(var m in chunks.Select(f=>f.sharedMesh).Distinct())File.Copy(AssetDatabase.GetAssetPath(m),backup+"/"+Path.GetFileName(AssetDatabase.GetAssetPath(m)));
var counts=walks.ToDictionary(s=>s,s=>0);var positions=new List<Vector3>();var previews=new Dictionary<int,Vector3>();int bound=0;
foreach(var f in chunks){var m=f.sharedMesh;var p=m.vertices;var info=m.uv2;var host=new List<Vector2>(Enumerable.Repeat(Vector2.zero,p.Length));
for(int i=0;i<p.Length;i+=4){var center=Enumerable.Range(i,4).Select(j=>f.transform.TransformPoint(p[j])).Aggregate(Vector3.zero,(a,b)=>a+b)/4;positions.Add(center);int tile=Mathf.RoundToInt(info[i].x);var s=Host(surfaces,center);if(s==null)throw new Exception("No native surface at "+center);for(int j=i;j<i+4;j++){if(!At(s,f.transform.TransformPoint(p[j]),out var uv))throw new Exception("Cover corner outside native surface");host[j]=uv;}bound++;if(tile==2&&counts.ContainsKey(s))counts[s]++;if(!previews.ContainsKey(tile))previews[tile]=center;}
m.SetUVs(4,host);EditorUtility.SetDirty(m);}
var tex=new Texture2D(2,2);tex.LoadImage(File.ReadAllBytes("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City Road Detail Atlas.png"));T.GetField("paint",Flags).SetValue(null,tex.GetPixels32());T.GetField("paintW",Flags).SetValue(null,tex.width);T.GetField("paintH",Flags).SetValue(null,tex.height);UnityEngine.Object.DestroyImmediate(tex);
var bt=T.GetNestedType("B",BindingFlags.NonPublic);int added=0;var sample=new List<Vector3>();foreach(var s in walks){var b=Field<Bounds>(s,"b");bool alongX=b.size.x>b.size.z;for(int target=counts[s];target<3;target++){bool placed=false;for(int attempt=0;attempt<1800;attempt++){var p=(Vector3)Call("RandomPoint",s);float part=Mathf.InverseLerp(alongX?b.min.x:b.min.z,alongX?b.max.x:b.max.z,alongX?p.x:p.z);if(attempt<900&&(part<target/3f+.035f||part>(target+1)/3f-.035f))continue;if(positions.Any(v=>Vector3.SqrMagnitude(v-p)<16))continue;var builder=Activator.CreateInstance(bt,true);float angle=alongX?90:0;if(!(bool)Call("Cover",s,p,.95f,.65f,angle,builder,2))continue;
var f=chunks.OrderBy(v=>(v.GetComponent<Renderer>().bounds.center-p).sqrMagnitude).First();var mesh=f.sharedMesh;var verts=mesh.vertices.ToList();var normals=mesh.normals.ToList();var uv0=mesh.uv.ToList();var uv1=mesh.uv2.ToList();var colors=mesh.colors.ToList();var host=new List<Vector2>();mesh.GetUVs(4,host);var ids=mesh.triangles.ToList();int start=verts.Count;var np=Field<List<Vector3>>(builder,"p");verts.AddRange(np.Select(f.transform.InverseTransformPoint));normals.AddRange(Enumerable.Repeat(Vector3.up,4));uv0.AddRange(Field<List<Vector2>>(builder,"uv"));uv1.AddRange(Field<List<Vector2>>(builder,"info"));colors.AddRange(Field<List<Color>>(builder,"c").Select(c=>new Color(c.r,c.g,c.b,2.5f/16)));foreach(var q in np){if(!At(s,q,out var u))throw new Exception("New drain corner");host.Add(u);}ids.AddRange(Field<List<int>>(builder,"ids").Select(v=>v+start));mesh.SetVertices(verts);mesh.SetNormals(normals);mesh.SetUVs(0,uv0);mesh.SetUVs(1,uv1);mesh.SetUVs(4,host);mesh.SetColors(colors);mesh.SetTriangles(ids,0);mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);positions.Add(p);sample.Add(p);counts[s]++;added++;placed=true;break;}
if(!placed)throw new Exception("Unable to place three drains on "+Field<MeshFilter>(s,"f").name);}
log.AppendLine(Field<MeshFilter>(s,"f").name+": "+counts[s]+" drain grilles");}
T.GetField("paint",Flags).SetValue(null,null);mat.SetTexture("_RoadBaseArray",AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/RoadAtlas/Road Atlas.mat").GetTexture("_RoadBaseArray"));EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();
foreach(var kv in previews.Where(k=>k.Key==0||k.Key==2))Photo(scene,kv.Value+new Vector3(1.5f,2,-1.7f),kv.Value,"Blended-Utility-"+kv.Key);
if(sample.Count>0){var p=sample[0];Photo(scene,p+new Vector3(6,13,-12),p,"Blended-Pathway-Drains");}
int errors=ShaderUtil.GetShaderMessages(mat.shader).Count(v=>v.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);
log.AppendLine("SUCCESS existing covers="+bound+"; added grilles="+added+"; eligible pathways="+walks.Length+"; minimum grilles="+counts.Values.Min()+"; visible batches="+chunks.Length+"; new runtime textures/materials/renderers=0; shader errors="+errors+"; backup="+backup);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/UtilityBlendReport.txt",log.ToString());}}
